<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CMS Dashboard</title><link rel="stylesheet" href="<?= htmlspecialchars(asset('css/style.css')) ?>"><style>.cms-admin{background:#f5f8fc;min-height:100vh}.cms-top{background:#fff;border-bottom:1px solid #e5edf7}.cms-top .inner{max-width:1180px;margin:auto;padding:18px 22px;display:flex;justify-content:space-between;align-items:center}.cms-main{max-width:1180px;margin:auto;padding:30px 22px}.cms-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cms-page{background:#fff;border:1px solid #e5edf7;border-radius:18px;padding:18px;box-shadow:0 14px 34px rgba(15,23,42,.06)}.cms-page h3{margin:0 0 8px}.cms-page a{display:inline-flex;margin-top:12px;background:#0646a8;color:#fff;padding:9px 13px;border-radius:999px;text-decoration:none;font-weight:800}.cms-logout{border:0;background:#eef6ff;color:#0646a8;border-radius:999px;padding:9px 13px;font-weight:800}@media(max-width:900px){.cms-grid{grid-template-columns:1fr}}</style></head><body><div class="cms-admin"><header class="cms-top"><div class="inner"><h1>Netedge CMS</h1><form method="post" action="<?= htmlspecialchars(str_replace('/index.php','',$_SERVER['SCRIPT_NAME'])) ?>/cms/logout"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><button class="cms-logout">Logout</button></form></div></header><main class="cms-main"><h2>Pages</h2><p>CMS-ready page registry. Edits are stored in <code>storage/cms/pages</code> for future CMS integration.</p><div class="cms-grid"><?php foreach($pages as $page): ?><div class="cms-page"><h3><?= htmlspecialchars($page['title'] ?? $page['slug']) ?></h3><code>/<?= htmlspecialchars($page['slug']) ?></code><br><a href="<?= htmlspecialchars(str_replace('/index.php','',$_SERVER['SCRIPT_NAME'])) ?>/cms/pages/<?= htmlspecialchars($page['slug']) ?>">Edit content</a></div><?php endforeach; ?></div></main></div></body></html>